    def removeTrailingZeros(self, num: str) -> str:
        # Start from the end and find the first non-zero digit
        for i in range(len(num) - 1, -1, -1):
            if num[i] != '0':
                # Found the last non-zero digit, return substring from start to this position
                return num[:i + 1]

        # This case should never happen since num is a positive integer
        # (it doesn't have leading zeros, so there must be at least one non-zero digit)
        return ""

class Solution:
    def removeTrailingZeros(self, num: str) -> str:
        # Find the last non-zero character from the end
        i = len(num) - 1
        while i >= 0 and num[i] == '0':
            i -= 1

        # Return substring from beginning to position i (inclusive)
        # If i is -1, it means all digits were zeros, but constraint says positive integer
        return num[:i + 1]

